export function getRouteSpiritArt(id: string, name = ""): RouteIconArt | undefined {
 if (id.startsWith("law_spirit_")) return ROUTE_LAW_ART[id.slice(11)];
 if (id === "path_of_democracy") {
  const match = name.match(/([0-5])\s*\/\s*5/);
  if (match) return ROUTE_SPIRIT_ART[`democracy_${match[1]}`];
  if (/完成/.test(name)) return ROUTE_SPIRIT_ART.democracy_5;
 }
 return ROUTE_SPIRIT_ART[id];
}
